user_criteria.script:
checkCondition();

function checkCondition() {
	var buEscolas = gs.getProperty('business_unit.escolas');
    var user = new GlideRecord('sys_user');
    user.get(user_id);

    if (((user.title.indexOf('DIRETOR E') != -1 || user.title.indexOf('VICE D') != -1 ||user.title.indexOf('GERENTE ADMINISTRATIVO ESCOLAR') != -1 || user.title.indexOf('COORDENADOR ADMINISTRATIVO') != -1 && user.department.business_unit == buEscolas)))
		{
        return true;
    } else {
		return false;
	}
}
